div.script:
(function(){
  function apply(l){
    document.documentElement.classList.toggle('abj-km', l==='km');
    var bs=document.querySelectorAll('.abj-langswitch button');
    for(var i=0;i<bs.length;i++){bs[i].classList.toggle('active', bs[i].getAttribute('data-lang')===l);}
    try{localStorage.setItem('abjLang', l);}catch(e){}
  }
  var saved='en';
  try{saved=localStorage.getItem('abjLang')||'en';}catch(e){}
  apply(saved);
  var bs=document.querySelectorAll('.abj-langswitch button');
  for(var i=0;i<bs.length;i++){
    bs[i].addEventListener('click', function(){apply(this.getAttribute('data-lang'));});
  }
})();
